int total = sums.stream().reduce(0, Integer::sum);
System.out.println("Suma calkowita: " + total);

List<Integer> numbers = List.of(5, 1, 9, 3, 8, 2, 7, 4, 6);
List<Integer> copy = new ArrayList<>(numbers);
List<Integer> top3 = new ArrayList<>();

for (int i = 0; i < 3; i++) {
    Optional<Integer> max = copy.stream().reduce(Integer::max);
    max.ifPresent(m -> {
        top3.add(m);
        copy.remove(m);
    });
}
System.out.println("Top 3 (malejaco): " + top3);
